/// Apply the given operation to every element of the input collection,
/// returning a new collection with the results.
pub fn map<T, U, F>(input: Vec<T>, mut function: F) -> Vec<U>
where
 F: FnMut(T) -> U,
{
 let mut result = Vec::with_capacity(input.len());
 for element in input {
 result.push(function(element));
 }
 result
}

/// Applies `function` to every element of `input` and returns a new vector
/// containing the results, in the same order.
pub fn map<T, U>(input: Vec<T>, function: impl FnMut(T) -> U) -> Vec<U> {
 let mut output = Vec::with_capacity(input.len());
 for element in input {
 output.push(function(element));
 }
 output
}
